"""Retain a scoped, source-bound inventory without merging experiment branches."""
import argparse,json,subprocess,hashlib
from pathlib import Path


def main():
    ap=argparse.ArgumentParser();ap.add_argument('--out',type=Path,required=True);a=ap.parse_args();cell=Path(__file__).resolve().parents[1];root=cell.parents[1]
    def commit(path):return subprocess.check_output(['git','log','-1','--format=%H','--',str(path.relative_to(root))],cwd=root,text=True).strip()
    def digest(path):return hashlib.sha256(path.read_bytes()).hexdigest()
    runs=[]
    for name in ['staged_accuracy08','capacity_accuracy09','correction_accuracy10']:
        run=cell/'runs'/name;panel=json.loads((run/'panel.json').read_text());audit=json.loads((run/'audit.json').read_text());archive=json.loads((run/'ARCHIVE.json').read_text());restoration=json.loads((run/'restoration-audit.json').read_text());assert audit['passed'] and restoration['passed'] and audit['remote_deleted'];allgroup=next(g for g in panel['groups'] if g['group']=='all');last=allgroup['meshes'][-1]
        checkpoints=[]
        for c in panel['checkpoints']:
            path=run/'checkpoints'/(c['id']+'.pkl');assert path.exists() and digest(path)==c['sha256'];checkpoints.append(dict(id=c['id'],path=str(path.relative_to(root)),sha256=c['sha256'],archive_commit=commit(path)))
        results={m:{key:v for key,v in data.items() if key in ['gpu_median_ms','host_median_ms','worst_relative_error','worst_adjusted_relative_error','all_cases_pass_target','invalid_invocations','nominal_latent_dimension','nonlinear_optimizer_dimension','correction_count','no_gpu_cost_regression_vs_frozen','no_host_cost_regression_vs_frozen']} for m,data in last['methods'].items()}
        runs.append(dict(name=name,scientific_source_commit=panel['source_commit'],archive_commit=commit(run/'ARCHIVE.json'),result_path=str((run/'result.json').relative_to(root)),result_sha256=digest(run/'result.json'),panel_path=str((run/'panel.json').relative_to(root)),audit_path=str((run/'audit.json').relative_to(root)),restoration_path=str((run/'restoration-audit.json').relative_to(root)),archive_manifest=str((run/'ARCHIVE.json').relative_to(root)),archive_sha256=archive['archive_sha256'],cleanup_path=str((run/'cleanup.json').relative_to(root)),checkpoints=checkpoints,finest_intervals=last['intervals'],all_opened_development_cases=allgroup['cases'],finest_results=results,bank_diagnostics=last['bank_diagnostics']))
    implementations=['core.py','speed_core.py','kernel_solver.py','iterative_core.py','tuning_core.py','pilot.py','staged_oracles.py','staged_cluster.py','capacity_cluster.py','test_staged_training.py','test_widen_bank.py','staged_accuracy.py','staged_training.py','capacity_accuracy.py','widen_bank.py','correction_core.py','correction_accuracy.py','correction_cluster.py','test_corrections.py','config-staged-accuracy.json','config-capacity-accuracy.json','config-correction-accuracy.json','STAGED-ACCURACY-DESIGN.md','CAPACITY-ACCURACY-DESIGN.md','CORRECTION-ACCURACY-DESIGN.md','reports/audit_staged_accuracy.py','reports/audit_capacity_accuracy.py','reports/audit_capacity_training.py','reports/audit_correction_accuracy.py','reports/diagnose_head_corrections.py','reports/summarize_correction_accuracy.py','reports/verify_split_archive.py']
    files=[dict(path=str((cell/p).relative_to(root)),sha256=digest(cell/p),last_change_commit=commit(cell/p)) for p in implementations if (cell/p).exists()]
    basis=cell/'runs/capacity_accuracy09/r128_joint-training-correction-basis.npz';out=dict(status='scoped integration inventory only; experiment branch remains separate',branch=subprocess.check_output(['git','branch','--show-current'],cwd=root,text=True).strip(),scope='Current-network Poisson staged training, bank expansion, then one frozen nested linear correction family; no final cases opened',implementations=files,runs=runs,correction_basis=dict(path=str(basis.relative_to(root)),sha256=digest(basis),archive_commit=commit(basis),diagnostic_path=str((basis.parent/'head-correction-diagnostic.json').relative_to(root))),integration_notes=['Do not merge automatically; root presents the requested merge decision','Staged08 and capacity09 are accepted numerical evidence of target failures, not successful physical-accuracy methods','Correction10 remains one frozen family with32 primary; its target and cost outcomes below are authoritative, regardless of acceptance of numerical audits','No training or source-family descriptors are needed online; exact supplied-source contraction and source-based training-code initialization are retained','Correction intervention adds linear capacity and analytic elimination; q0 parity and old-manifold inclusion are audited','All correction prefixes share the fixed128 bank and retain the separate3% bank diagnostic target','Original5% adjusted physical/numerical target is never relaxed; no universal FOM speed advantage is claimed','All full fields, repetitions, references and raw checkpoints restore from ordered archive parts'])
    a.out.mkdir(parents=True,exist_ok=True);(a.out/'integration-inventory.json').write_text(json.dumps(out,indent=2)+'\n')
    lines=['# Poisson accuracy campaign integration inventory','','All runs below are numerically audited and retained. Accuracy eligibility is shown separately. The experiment branch remains separate; no merge has been performed.','','| Run | Source commit | Archive commit | Model | Finest error % | GPU ms | Host ms | Pass5% | Invalid calls |','|---|---|---|---|---:|---:|---:|---|---:|']
    for r in runs:
        for m,v in r['finest_results'].items():
            if m.startswith('cg_') or m=='dst':continue
            lines.append(f"| {r['name']} | `{r['scientific_source_commit']}` | `{r['archive_commit']}` | {m} | {100*v['worst_relative_error']:.6f} | {v['gpu_median_ms']:.6f} | {v['host_median_ms']:.6f} | {v['all_cases_pass_target']} | {v['invalid_invocations']} |")
    lines+=['','Runtime columns are comparable within each run only. Exact paths, hashes, base-bank diagnostic target outcomes and retained implementation files are in `integration-inventory.json`.','',*out['integration_notes'],'','## Glossary','','Run: one isolated GPU job and archive. Source commit: frozen scientific implementation used by that job. Archive commit: commit retaining the checked result parts. Finest error: worst current-relative full-field error over all opened development cases at the finest mesh. GPU ms: pooled median device query time. Host ms: pooled median time including transfers. Pass5%: all cases pass adjusted physical error, reference refinement and numerical validity. Invalid calls: retained invocations failing numerical gates. Bank target: separate3% full-span projection diagnostic. Prefix:8,16 or32 columns of the same fixed training-only correction basis.']
    (a.out/'INTEGRATION-INVENTORY.md').write_text('\n'.join(lines)+'\n');print(a.out/'integration-inventory.json')


if __name__=='__main__':main()
